import numpy as np,json,itertools
from pathlib import Path
O=np.load('/challenge/observations.npz');X=O['tokens'];P=O['probabilities']; y=P[:,4:].argmax(-1).ravel(); F=np.stack([X[:,4-k:24-k].ravel() for k in range(1,5)],1)
print('Top-vs-observed',np.mean(y==X[:,4:].ravel()))
for k in range(1,5):
 for j in range(k,5):
  inds=F[:,k-1]*16+F[:,j-1];tab=np.zeros((256,16),int);np.add.at(tab,(inds,y),1)
  print('lag pair',k,j,'majority',tab.max(1).sum()/len(y),'support',int((tab.sum(1)>0).sum()))
# exhaustive modular linear recurrence, held-out examples
coef=np.array(list(itertools.product(range(16),repeat=4)),dtype=np.int16)
best=[]
for start in range(0,len(coef),1024):
 c=coef[start:start+1024];pred=(c@F[:512].T)%16
 for b in range(16):
  score=(pred==(y[:512][None]-b)%16).mean(1);i=score.argmax();best.append((score[i],c[i].tolist(),b))
best=sorted(best,reverse=True)[:8];print('best mod16',best)
for s,c,b in best[:3]:print('full score',c,b,np.mean((F@c+b)%16==y))
# xor-linear tests, each lag expanded to bits
B=((F[:,:,None]>>np.arange(4))&1).reshape(-1,16)
B=np.column_stack([B,np.ones(len(B),int)])
for bit in range(4):
 target=(y>>bit)&1
 a=np.column_stack([B,target]).astype(np.uint8);rank=0;piv=[]
 for j in range(17):
  ii=np.flatnonzero(a[rank:,j]);
  if not len(ii):continue
  i=rank+ii[0];a[[rank,i]]=a[[i,rank]]
  for i in np.flatnonzero(a[:,j]):
   if i!=rank:a[i]^=a[rank]
  piv.append(j);rank+=1
 inconsistent=np.sum((a[:,:17].sum(1)==0)&(a[:,17]!=0));print('GF2 bit',bit,'rank',rank,'inconsistent',inconsistent)
print('single symbolic combos')
for a,b in itertools.combinations(range(4),2):
 for name,v in [('sum',(F[:,a]+F[:,b])%16),('diff',(F[:,a]-F[:,b])%16),('xor',F[:,a]^F[:,b])]:
  t=np.zeros((16,16),int);np.add.at(t,(v,y),1);score=t.max(1).sum()/len(y)
  if score>.2:print(a+1,b+1,name,round(score,4),'map',t.argmax(1).tolist())
Path('/output/search1.json').write_text(json.dumps({'best_linear_mod16':best,'top_truth_agreement':float(np.mean(y==X[:,4:].ravel()))}))

from pathlib import Path
import numpy as np,json
D=Path('/output'); z=np.load(D/'calibration_data.npz');X=z['X'];P=z['P'];perm=np.load(D/'structural_params.npz')['permutation'];n=len(X)
row=np.repeat(np.arange(n),20);pos=np.tile(np.arange(4,24),n);Y=P[:,4:].reshape(-1,16);src=X[row,pos-4];star=perm[src];ii=np.arange(len(Y));isstar=np.arange(16)[None]==star[:,None];pt=Y[ii,star]
train=((row<96)|((row>=128)&(row<320)));vobs=(row>=96)&(row<128);vind=row>=320
one=np.eye(16); names=['intercept','source','position','lag1','lag7'];F=np.column_stack([np.ones(len(Y)),one[src],np.eye(20)[pos-4],one[X[row,pos-1]],one[X[row,np.maximum(pos-7,0)]]*(pos>=7)[:,None]])
A=np.log(pt/(1-pt));B=np.log(Y/(1-pt[:,None]));B-=np.sum(np.where(isstar,0,B),1)[:,None]/15;B[isstar]=0
# The missing target entry of each off-target logit is irrelevant at prediction.
def soft(z,mask):
 z=np.where(mask,-1e6,z);z-=z.max(1,keepdims=True);z=np.exp(z);return z/z.sum(1,keepdims=True)
def kl(y,q):return float((y*(np.log(y)-np.log(q))).sum(1).mean())
def fit(F,T,ridge=1,mask=None):
 if mask is None:
  R=np.eye(F.shape[1])*ridge;R[0,0]=.001;return np.linalg.solve(F[train].T@F[train]+R,F[train].T@T[train])
 W=np.zeros((F.shape[1],16));R=np.eye(F.shape[1])*ridge;R[0,0]=.001
 for j in range(16):
  use=train&~mask[:,j];W[:,j]=np.linalg.solve(F[use].T@F[use]+R,F[use].T@T[use,j])
 return W
BW=fit(F,B,mask=isstar);noise=soft(F@BW,isstar)
print('off-target conditional KL',kl(np.where(isstar,0,Y/(1-pt[:,None]))+isstar*1e-200,noise+isstar*1e-200))
results=[]
for style in ['main','source_position','source_last','source_position_last','source_position_lag7']:
 C=[F]
 if 'position' in style:C.append((one[src,:,None]*np.eye(20)[pos-4,None,:]).reshape(-1,320))
 if 'last' in style:C.append((one[src,:,None]*one[X[row,pos-1],None,:]).reshape(-1,256))
 if 'lag7' in style:C.append((one[src,:,None]*one[X[row,np.maximum(pos-7,0)],None,:]).reshape(-1,256)*(pos>=7)[:,None])
 G=np.column_stack(C)
 for ridge in [1,10]:
  AW=fit(G,A,ridge);p=1/(1+np.exp(-(G@AW)));q=noise*(1-p[:,None]);q[ii,star]=p
  result={'style':style,'ridge':ridge,'parameters':int(BW.size+AW.size),'cached_KL':kl(Y[vobs],q[vobs]),'independent_KL':kl(Y[vind],q[vind])};results.append(result);print(result)
(D/'factorized_search.json').write_text(json.dumps(results,indent=2))
print('current accounting', (D/'accounting.json').read_text())
print('submission files',[(p.name,p.stat().st_size) for p in (D/'submission').iterdir()])

